/**
 * End-to-end test of LIVE generation (run against a gemini container).
 *
 * There are no canned specs — every UI here is generated by the model on the
 * fly, proving it pulls from its toolbox: registry components, the sandboxed
 * CustomWidget, and the freeform ReactArtifact lane. Assertions are resilient
 * (shape, not exact output) because the model's output legitimately varies.
 *
 * Usage: BASE_URL=http://localhost:8080 node scripts/e2e.mjs
 */
import { chromium } from 'playwright';
import { mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const BASE = process.env.BASE_URL || 'http://localhost:8080';
const SHOTS = join(dirname(fileURLToPath(import.meta.url)), 'screens');
mkdirSync(SHOTS, { recursive: true });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const results = [];
const check = (name, cond, detail = '') => {
  results.push({ name, ok: !!cond });
  console.log(`${cond ? '[PASS]' : '[FAIL]'} ${name}${detail ? ' — ' + detail : ''}`);
};
const statValues = (page) => page.$$eval('.text-2xl.font-semibold', (els) => els.map((e) => e.textContent.trim()));
async function moveSliderMax(slider) {
  const max = (await slider.getAttribute('max')) || '100';
  await slider.evaluate((el, v) => {
    const s = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    s.call(el, String(v));
    el.dispatchEvent(new Event('input', { bubbles: true }));
  }, max);
}
async function generate(page, prompt) {
  const box = page.getByRole('textbox').first();
  await box.fill(prompt);
  await box.press('Enter');
}

const run = async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1100, height: 950 } });
  const errors = [];
  page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
  page.on('pageerror', (e) => errors.push(String(e)));

  try {
    await page.goto(`${BASE}?noauto=1`, { waitUntil: 'domcontentloaded' });
    await page.getByRole('heading', { name: /describe an interface/i }).waitFor({ timeout: 10000 });
    check('landing renders', true);

    // 1) Registry tool — a stateful, interactive widget
    await generate(page, 'a tip calculator with sliders for bill, tip percent and number of people, showing the total');
    await page.waitForSelector('input[type=range]', { timeout: 75000 });
    await sleep(800);
    const before = await statValues(page);
    await moveSliderMax(page.locator('input[type=range]').first());
    await sleep(400);
    const after = await statValues(page);
    check('registry UI generated + interactive', before.length >= 1 && JSON.stringify(before) !== JSON.stringify(after),
      `${JSON.stringify(before)} -> ${JSON.stringify(after)}`);
    await page.screenshot({ path: join(SHOTS, 'gen-1-registry.png') });

    // 2) Sandbox/freeform tool — a real game in an iframe
    await generate(page, 'a fully playable snake game with arrow-key controls and a score');
    await page.waitForSelector('iframe[title="custom-widget"], iframe[title="react-artifact"]', { timeout: 85000 });
    await sleep(1500);
    const frames = await page.$$('iframe[title="custom-widget"], iframe[title="react-artifact"]');
    check('sandbox/freeform game generated (iframe mounts)', frames.length >= 1, `${frames.length} iframe(s)`);
    await page.screenshot({ path: join(SHOTS, 'gen-2-game.png') });

    // 3) Freeform tool — a bespoke React+Tailwind design
    await generate(page, 'a beautifully designed glassmorphism pricing card');
    await page.waitForSelector('iframe[title="react-artifact"]', { timeout: 85000 });
    await sleep(6000); // CDN + transpile + render
    const errPane = await page.frameLocator('iframe[title="react-artifact"]').locator('pre').count().catch(() => 0);
    check('freeform ReactArtifact generated + rendered clean', errPane === 0, errPane ? 'error pane shown' : 'ok');
    await page.screenshot({ path: join(SHOTS, 'gen-3-freeform.png') });

    check('no parent console errors', errors.length === 0, errors.slice(0, 3).join(' | '));
  } finally {
    await browser.close();
  }

  const failed = results.filter((r) => !r.ok);
  console.log(`\nSUMMARY: ${results.length - failed.length}/${results.length} passed`);
  console.log(`Screenshots: ${SHOTS}`);
  if (failed.length) process.exit(1);
};

run().catch((e) => {
  console.error('E2E crashed:', e);
  process.exit(2);
});
